package com.jmadsen.dashhop;
import android.Manifest;import android.content.*;import android.content.pm.PackageManager;import android.database.Cursor;import android.graphics.Color;import android.provider.CalendarContract;import android.view.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;
/** Calendar provider data is rendered locally only and never included in Diagnostics. */
final class CalendarUtility extends LinearLayout {
 final Context c;final CalendarPanel dates;final LinearLayout content;final ExecutorService worker=Executors.newSingleThreadExecutor();boolean attached;
 CalendarUtility(Context c){super(c);this.c=c;setOrientation(1);LinearLayout actions=new LinearLayout(c);actions.addView(action("Events / Agenda",this::agenda),new LinearLayout.LayoutParams(0,UtilityPopupManager.px(48),1));actions.addView(action("Add event",this::addEvent),new LinearLayout.LayoutParams(0,UtilityPopupManager.px(48),1));actions.addView(action("Calendar access",()->AppLaunchManager.settings(c,"calendar")),new LinearLayout.LayoutParams(0,UtilityPopupManager.px(48),1));addView(actions);content=new LinearLayout(c);content.setOrientation(1);addView(content,new LinearLayout.LayoutParams(-1,0,1));dates=new CalendarPanel(c,new ShortcutRepository(c),"utilityCalendar");dates.mode="month";dates.onDaySelected=this::agenda;dates.render();showDates();}
 TextView text(String s,int size){TextView t=new TextView(c);t.setText(s);t.setTextSize(size);t.setTextColor(Color.WHITE);t.setPadding(10,10,10,10);return t;}TextView action(String s,Runnable r){TextView t=text(s,16);t.setMinHeight(DockController.px(c,48));t.setGravity(Gravity.CENTER);t.setOnClickListener(v->r.run());return t;}
 void showDates(){content.removeAllViews();if(dates.getParent()!=null)((ViewGroup)dates.getParent()).removeView(dates);content.addView(dates,new LinearLayout.LayoutParams(-1,-1));}
 void back(){if(dates.getParent()==content){if(!dates.mode.equals("month")){dates.mode="month";dates.onDaySelected=this::agenda;dates.render();}else UtilityPopupManager.dismiss();}else showDates();}
 boolean allowed(String permission){return c.checkSelfPermission(permission)==PackageManager.PERMISSION_GRANTED;}
 void agenda(){content.removeAllViews();content.addView(text("Loading selected date and upcoming events…",18));if(!allowed(Manifest.permission.READ_CALENDAR)){content.removeAllViews();content.addView(text("Local date browsing is available. Enable calendar read access in Settings for synced events.",18));return;}long start=dates.cursor.getTimeInMillis();Calendar day=(Calendar)dates.cursor.clone();day.set(Calendar.HOUR_OF_DAY,0);day.set(Calendar.MINUTE,0);day.set(Calendar.SECOND,0);start=day.getTimeInMillis();final long begin=start,end=start+7*86400000L;worker.execute(()->{List<Event> events=new ArrayList<>();try{android.net.Uri.Builder uri=CalendarContract.Instances.CONTENT_URI.buildUpon();ContentUris.appendId(uri,begin);ContentUris.appendId(uri,end);try(Cursor cursor=c.getContentResolver().query(uri.build(),new String[]{CalendarContract.Instances.TITLE,CalendarContract.Instances.BEGIN,CalendarContract.Instances.END,CalendarContract.Instances.DISPLAY_COLOR,CalendarContract.Instances.EVENT_LOCATION,CalendarContract.Instances.DESCRIPTION},null,null,CalendarContract.Instances.BEGIN+" ASC")){if(cursor!=null)while(cursor.moveToNext()&&events.size()<100)events.add(new Event(cursor.getString(0),cursor.getLong(1),cursor.getLong(2),cursor.getInt(3),cursor.getString(4),cursor.getString(5)));}post(()->renderEvents(events));}catch(Exception e){Diagnostics.error("calendar_provider_read_failed",e);post(()->{content.removeAllViews();content.addView(text("Calendar provider unavailable. Local calendar remains available.",18));});}});}
 static final class Event {String title,location,description;long start,end;int color;Event(String t,long s,long e,int c,String l,String d){title=t;start=s;end=e;color=c;location=l;description=d;}}
 void renderEvents(List<Event> events){if(!attached)return;content.removeAllViews();ScrollView scroll=new ScrollView(c);LinearLayout list=new LinearLayout(c);list.setOrientation(1);scroll.addView(list);content.addView(scroll,new LinearLayout.LayoutParams(-1,-1));if(events.isEmpty())list.addView(text("No events in this seven-day period",18));for(Event event:events){TextView row=action(java.text.DateFormat.getDateTimeInstance(java.text.DateFormat.SHORT,java.text.DateFormat.SHORT).format(new Date(event.start))+"\n"+event.title,()->{content.removeAllViews();ScrollView details=new ScrollView(c);LinearLayout fields=new LinearLayout(c);fields.setOrientation(1);fields.addView(text(event.title,24));fields.addView(text(new Date(event.start)+"\n"+new Date(event.end),16));fields.addView(text(event.location==null?"":event.location,16));fields.addView(text(event.description==null?"":event.description,16));fields.addView(action("Back to agenda",this::agenda));details.addView(fields);content.addView(details);});row.setBackgroundColor(event.color==0?0xff256073:0xff000000|(event.color&0xffffff));list.addView(row);}}
 void addEvent(){if(!allowed(Manifest.permission.READ_CALENDAR)||!allowed(Manifest.permission.WRITE_CALENDAR)){content.removeAllViews();content.addView(text("Grant calendar read/write access in Settings to add an event. A writable calendar account/provider is required.",18));return;}List<Long> ids=new ArrayList<>();List<String> names=new ArrayList<>();try(Cursor calendars=c.getContentResolver().query(CalendarContract.Calendars.CONTENT_URI,new String[]{CalendarContract.Calendars._ID,CalendarContract.Calendars.CALENDAR_DISPLAY_NAME},CalendarContract.Calendars.CALENDAR_ACCESS_LEVEL+">=?",new String[]{Integer.toString(CalendarContract.Calendars.CAL_ACCESS_CONTRIBUTOR)},null)){if(calendars!=null)while(calendars.moveToNext()){ids.add(calendars.getLong(0));names.add(calendars.getString(1));}}catch(Exception e){Diagnostics.error("calendar_provider_list_failed",e);}if(ids.isEmpty()){content.removeAllViews();content.addView(text("No writable Android calendar is available. Add/sync an account through Android settings.",18));return;}
 content.removeAllViews();ScrollView scroll=new ScrollView(c);LinearLayout form=new LinearLayout(c);form.setOrientation(1);EditText title=new EditText(c);title.setHint("Event title");title.setTextColor(Color.WHITE);form.addView(title);Spinner calendar=new Spinner(c);calendar.setAdapter(new ArrayAdapter<>(c,android.R.layout.simple_spinner_dropdown_item,names));form.addView(calendar);DatePicker date=new DatePicker(c);date.init(dates.cursor.get(Calendar.YEAR),dates.cursor.get(Calendar.MONTH),dates.cursor.get(Calendar.DAY_OF_MONTH),null);form.addView(date);TimePicker time=new TimePicker(c);time.setIs24HourView(android.text.format.DateFormat.is24HourFormat(c));form.addView(time);EditText duration=new EditText(c);duration.setHint("Duration in minutes");duration.setText("60");duration.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);duration.setTextColor(Color.WHITE);form.addView(duration);form.addView(action("Save event",()->{try{Calendar start=Calendar.getInstance();start.set(date.getYear(),date.getMonth(),date.getDayOfMonth(),time.getHour(),time.getMinute(),0);int minutes=Math.max(1,Math.min(10080,Integer.parseInt(duration.getText().toString())));ContentValues v=new ContentValues();v.put(CalendarContract.Events.CALENDAR_ID,ids.get(calendar.getSelectedItemPosition()));v.put(CalendarContract.Events.TITLE,title.getText().toString().trim().isEmpty()?"Untitled event":title.getText().toString());v.put(CalendarContract.Events.DTSTART,start.getTimeInMillis());v.put(CalendarContract.Events.DTEND,start.getTimeInMillis()+minutes*60000L);v.put(CalendarContract.Events.EVENT_TIMEZONE,TimeZone.getDefault().getID());if(c.getContentResolver().insert(CalendarContract.Events.CONTENT_URI,v)==null)throw new IllegalStateException("Provider declined");Diagnostics.info("calendar_event_insert_succeeded_no_content_logged");dates.cursor=start;agenda();}catch(Exception e){Diagnostics.error("calendar_event_insert_failed",e);Toast.makeText(c,"Unable to save event; check calendar provider and fields",Toast.LENGTH_LONG).show();}}));form.addView(action("Cancel",this::showDates));scroll.addView(form);content.addView(scroll,new LinearLayout.LayoutParams(-1,-1));}
 protected void onAttachedToWindow(){super.onAttachedToWindow();attached=true;}protected void onDetachedFromWindow(){attached=false;worker.shutdownNow();super.onDetachedFromWindow();}
}
